    """Return a 3x3 tile in the color of the largest solid-color object."""
    h, w = len(grid), len(grid[0])
    seen = set()
    largest = (0, 0)
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            size = 0
            while stack:
                y, x = stack.pop()
                size += 1
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
